# Find all maximal runs of 8s in demo input and see which ones become 4s
def find_8_runs(grid):
    runs = []
    for r in range(len(grid)):
        c = 0
        while c < len(grid[r]):
            if grid[r][c] == 8:
                start = c
                while c < len(grid[r]) and grid[r][c] == 8:
                    c += 1
                runs.append((r, start, c-1, c-start))
            else:
                c += 1
    return runs

