# Find all maximal rectangles of 8s
def find_rectangles_of_8(grid, min_height=2, min_width=2):
    rects = []
    h, w = len(grid), len(grid[0])
    visited = set()

    # Check every possible top-left corner
    for r1 in range(h):
        for c1 in range(w):
            if grid[r1][c1] != 8 or (r1, c1) in visited:
                continue

            # Find max rectangle starting at (r1, c1)
            max_h, max_w = 1, 1
            for r in range(1, h - r1):
                # Try to extend horizontally
                for c in range(1, w - c1 + 1):
                    if grid[r1+r][c1+c-1] == 8:
                        max_w = max(max_w, c)
                    else:
                        break

                # Check if we can form rectangle of size (r+1) x max_w
                if max_w >= min_width:
                    try_count = 0
                    for tr in range(r1, r1+r+1):
                        for tc in range(c1, c1+max_w):
                            if grid[tr][tc] == 8 and (tr, tc) not in visited:
                                pass
                            elif (tr, tc) in visited:
                                pass

                    # Simpler approach: expand greedily
                    height = 1
                    width = 1
                    valid_cells = {(r1, c1)}

                    while True:
                        found = False
                        for dr in range(height, h - r1):
                            row_ok = all(grid[dr][c1 + dc] == 8 for dc in range(width))
                            if row_ok:
                                found = True
                                valid_cells.add((dr, c1 + dc) for dr in [range(height, dr+1)] for dc in [range(width)])
                                height += 1
                                break
                        if not found:
                            break

                        for dc in range(width + 1):
                            col_ok = all(grid[r][c1 + dc] == 8 for r in range(height))
                            if col_ok:
                                found = True
                                width += 1
                                break

                        if not found:
                            break

                    if height >= min_height and width >= min_width:
                        rects.append((r1, c1, height-1, width-1))

    # Simple greedy detection of rectangular blocks of 8s
    rects_simple = []
    for r in range(h):
        i = 0
        while i < w:
            if grid[r][i] == 8:
                start_c = i
                end_c = i
                while end_c < w and grid[r][end_c] == 8:
                    end_c += 1
                length = end_c - start_c

                # Check how many consecutive rows have this exact pattern
                height = 1
                for rr in range(r+1, h):
                    if rr < h and end_c < w and all(grid[rr][cc] == 8 for cc in range(start_c, end_c)):
                        height += 1
                    else:
                        break

                if height >= 2 and length >= 2:
                    rects_simple.append((r, start_c, height-1, end_c-start_c-1))
                    # Mark as visited
                    for rr in range(r, r+height):
                        for cc in range(start_c, end_c):
                            visited.add((rr, cc))
            i += 1

    print("Rectangular blocks of 8s (height>=2, width>=2):")
    for rect in sorted(rects_simple):
        print(f"  Rows {rect[0]}-{rect[2]}, Cols {rect[1]}-{rect[3]}")
    return rects_simple

