# Find rectangular blocks of 8s more carefully
def find_rectangles_of_8(grid):
    h, w = len(grid), len(grid[0])

    # Simple approach: iterate through each cell and expand to find rectangles
    visited = set()
    rects = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 8 or (r, c) in visited:
                continue

            # Try to expand into a rectangle starting at (r, c)
            # First, find max width from this position in row r
            max_width = 1
            while c + max_width < w and grid[r][c + max_width] == 8:
                max_width += 1

            # Then find max height where this pattern continues
            max_height = 1
            rect_end_r = -1
            rect_end_c = -1

            while True:
                # Check if next row has 8s from c to c+max_width-1
                can_extend_down = True
                for dc in range(max_width):
                    if grid[r + max_height][c + dc] != 8:
                        can_extend_down = False
                        break

                if not can_extend_down:
                    break

                max_height += 1
                # Also try to extend width now
                new_max_width = max_width
                while c + new_max_width < w:
                    row_ok = True
                    for hr in range(max_height):
                        if grid[r + hr][c + new_max_width] != 8:
                            row_ok = False
                            break
                    if row_ok:
                        new_max_width += 1
                    else:
                        break

                if new_max_width > max_width:
                    max_width = new_max_width
                    rect_end_c = c + max_width - 1
                    if r + max_height - 1 >= rect_end_r:
                        rect_end_r = r + max_height - 1
                else:
                    rect_end_c = c + max_width - 1
                    if r + max_height - 1 >= rect_end_r:
                        rect_end_r = r + max_height - 1

            rect_start_r = r
            rect_start_c = c
            rect_height = rect_end_r - rect_start_r + 1 if rect_end_r != -1 else 1
            rect_width = rect_end_c - rect_start_c + 1 if rect_end_c != -1 else 1

            print(f"Found potential rect: rows {rect_start_r}-{rect_end_r}, cols {rect_start_c}-{rect_end_c} (size: {rect_height}x{rect_width})")

            if rect_height >= 2 and rect_width >= 5:  # Looking for reasonably large rectangles
                rects.append((rect_start_r, rect_start_c, rect_height, rect_width))

                # Mark visited
                for rr in range(rect_start_r, rect_start_r + rect_height):
                    for cc in range(rect_start_c, rect_start_c + rect_width):
                        visited.add((rr, cc))

    return rects

