hmin, wmin = 5, 5

def find_uniform_rectangles(grid, hmin=5, wmin=5):
    result = []
    visited = set()

    for r_start in range(len(grid)):
        for c_start in range(len(grid[0])):
            if (r_start, c_start) in visited:
                continue

            start_val = grid[r_start][c_start]

            # Find max width in first row
            max_w = 1
            while c_start + max_w < len(grid[0]):
                if grid[r_start][c_start + max_w] == start_val:
