            max_h = 1
            for r in range(1, len(grid) - r_start):
                row_ok = True
                for c in range(max_w):
                    if grid[r_start + r][c_start + c] != start_val:
                        row_ok = False
                        break
                if row_ok:
                    max_h += 1
                else:
                    break

