from collections import defaultdict

def find_runs(grid_row):
    """Find consecutive runs of identical values"""
    runs = []
    if not grid_row:
        return runs
    current_val = grid_row[0]
    count = 1
    for i in range(1, len(grid_row)):
        if grid_row[i] == current_val:
            count += 1
        else:
            runs.append((current_val, count))
            current_val = grid_row[i]
            count = 1
    runs.append((current_val, count))
    return runs

# Find all long horizontal runs (>= 5) in demo input
long_runs_by_col_range = defaultdict(list)
for r in range(30):
    row_vals = [demo_input[r][c] for c in range(30)]
    runs = find_runs(row_vals)
